const { formatTotal } = require('./format');
function summary(row) {
  const order = { id: row.id, total: row.amount_cents / 100 };
  if (row.status === 'draft') delete order.total;
  return `${order.id}: ${formatTotal(order)}`;
}
module.exports = { summary };

